(function(root){
'use strict';
var Core=root.V3Core;
var assetHeaders=['graph_id','snapshot_id','asset_id','asset_name','asset_kind','source_system','layer','domain','owner','steward','description','update_frequency','approximate_row_count','lineage_reference','pii_status','sensitivity','status','physical_asset_name','physical_binding_status','field_count','upstream_asset_ids_json','downstream_asset_ids_json','evidence_json','notes_json','metadata_json'];
var fieldHeaders=['graph_id','snapshot_id','field_id','asset_id','field_name','business_name','field_kind','source_system','layer','data_type','description','description_origin','business_definition','definition_status','business_review_json','source_file','record_reference','record_key_reference','attribute_position','value_position','subvalue_position','source_locator','physical_binding_status','extract_file','extract_position','hvr_header','upstream_field_ids_json','downstream_field_ids_json','transformation_logic_json','sample_values_json','allowed_values_json','nullable','is_pii','is_primary_key','foreign_key_reference','business_rules_json','last_verified_date','notes_json','evidence_json','metadata_json','original_field_json'];
var mappingHeaders=['graph_id','snapshot_id','source_field_id','source_asset_id','hvr_field_id','hvr_asset_id','target_asset_id'];
var descriptionKeys=['source_type','author','generator','source_reference','source_pointer','provenance_json'];
fieldHeaders=fieldHeaders.concat(descriptionKeys.map(function(k){return 'description_'+k;}));mappingHeaders=mappingHeaders.concat(['source_description_','snowflake_description_'].flatMap(function(prefix){return descriptionKeys.map(function(k){return prefix+k;});}));
var sourceInvariantHeaders=['source_field_id','source_asset_id','hvr_field_id','hvr_asset_id','ultracs_field_id','ultracs_field_name','source_name_origin','business_field_label','identity_scope','source_locator','source_references_json','source_program','ultracs_source_path','hvr_parameter_source_path','source_description','source_description_origin','business_definition','definition_status','business_review_json','extract_file','extract_column','extract_position','basic_expression','basic_transformation','basic_comment','basic_source_line','hvr_type','hvr_obfuscation','hvr_cleanup_json','hvr_cleanup_enabled','hvr_cleanup_remove_chars_json','primary_target_field_id','source_primary_target_json','original_mapping_confidence','original_mapping_notes','original_record_json','source_file','source_record_reference','source_record_key_reference','source_attribute_position','source_value_position','source_subvalue_position','source_file_binding_status'].concat(descriptionKeys.map(function(k){return 'source_description_'+k;}));
mappingHeaders=Array.from(new Set(mappingHeaders.concat(sourceInvariantHeaders)));
var text=function(v){return v==null?'':String(v);};
var object=function(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);};
var fail=function(m){throw new Error(m);};
var key=function(r,id){return JSON.stringify([r.graph_id,r.snapshot_id,id]);};
var scope=function(r){return JSON.stringify([r.graph_id,r.snapshot_id]);};
function parseRegistry(csv,required,id,label){
 var parsed=Core.parseCSV(csv), seen=new Set();
 required.forEach(function(h){if(!parsed.headers.includes(h))fail(label+' is missing required column: '+h);});
 var rows=parsed.rows.map(function(raw,n){
  if(!raw.graph_id||!raw.snapshot_id||!raw[id])fail(label+' record '+(n+2)+' has an empty graph, snapshot or '+id+'.');
  var k=key(raw,raw[id]);if(seen.has(k))fail(label+' contains duplicate '+id+': '+raw[id]);seen.add(k);
  var json={};parsed.headers.forEach(function(h){if(/_json$/.test(h)){try{json[h]=raw[h].trim()===''?null:JSON.parse(raw[h]);}catch(e){fail(label+' '+raw[id]+' has invalid JSON in '+h+'.');}}});
  return {raw:raw,json:json,id:raw[id],key:k,scope:scope(raw)};
 });
 return {headers:parsed.headers,rows:rows};
}
function stable(v){if(Array.isArray(v))return '['+v.map(stable).join(',')+']';if(object(v))return '{'+Object.keys(v).sort().map(function(k){return JSON.stringify(k)+':'+stable(v[k]);}).join(',')+'}';return JSON.stringify(v);}
function arrayIDs(v,label){if(!Array.isArray(v)||v.some(function(x){return typeof x!=='string'||!x;}))fail(label+' must be a JSON array of IDs.');if(new Set(v).size!==v.length)fail(label+' contains duplicate IDs.');return v;}
function validateDescription(raw,json,prefix,description,label){var type=raw[prefix+'source_type'];if(!['ai_generated','existing_metadata','unknown','not_supplied'].includes(type))fail(label+' has an invalid description source type.');if((text(description).trim()==='')!==(type==='not_supplied'))fail(label+' description availability disagrees with its source type.');var p=json[prefix+'provenance_json'];if(!object(p)||p.source_type!==type)fail(label+' description provenance must record the same source type.');}
function prepareBundle(files,manifest){
 if(!object(files))fail('Select all three CSV files together.');
 ['asset_registry.csv','field_catalog.csv','data_dictionary.csv'].forEach(function(f){if(typeof files[f]!=='string')fail('Bundle is incomplete. Missing '+f+'.');});
 var assets=parseRegistry(files['asset_registry.csv'],assetHeaders,'asset_id','Asset registry');
 var fields=parseRegistry(files['field_catalog.csv'],fieldHeaders,'field_id','Field catalog');
 var parsed=Core.parseCSV(files['data_dictionary.csv']);mappingHeaders.forEach(function(h){if(!parsed.headers.includes(h))fail('Data dictionary is missing required column: '+h);});
 var groups=new Map();parsed.rows.forEach(function(r,n){if(!r.graph_id||!r.snapshot_id)fail('Dictionary record '+(n+2)+' has no graph or snapshot ID.');var k=scope(r);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);});
 var rows=[],operations=new Map();groups.forEach(function(rs,k){var prepared=Core.prepareDataset({headers:parsed.headers,rows:rs});prepared.rows.forEach(function(r){r.graphId=r.raw.graph_id;r.scope=k;r.key=key(r.raw,r.id);rows.push(r);r.ops.forEach(function(op){operations.set(key(r.raw,op.relationship_id),op);});});});
 if(!rows.length)fail('The dictionary has no data rows.');
 var sourceDefinitions=new Map();rows.forEach(function(r){var sourceKey=JSON.stringify([r.scope,r.sourceId]),definition={};sourceInvariantHeaders.forEach(function(h){definition[h]=Object.prototype.hasOwnProperty.call(r.json,h)?r.json[h]:r.raw[h];});var encoded=stable(definition);if(sourceDefinitions.has(sourceKey)&&sourceDefinitions.get(sourceKey)!==encoded)fail('Conflicting identity or metadata for repeated source mapping: '+r.sourceId);sourceDefinitions.set(sourceKey,encoded);});
 var aMap=new Map(assets.rows.map(function(r){return [r.key,r];})),fMap=new Map(fields.rows.map(function(r){return [r.key,r];}));
 var scopes=[new Set(rows.map(function(r){return r.scope;})),new Set(assets.rows.map(function(r){return r.scope;})),new Set(fields.rows.map(function(r){return r.scope;}))];
 scopes.forEach(function(s){if(s.size!==scopes[0].size||Array.from(s).some(function(k){return !scopes[0].has(k);}))fail('The three CSV files contain different graph/snapshot sets. Import a matching bundle.');});
 var fk=function(map,raw,id,label){if(!id||!map.has(key(raw,id)))fail(label+' refers to a missing or cross-graph ID: '+(id||'(empty)'));return map.get(key(raw,id));};
 assets.rows.forEach(function(r){['upstream_asset_ids_json','downstream_asset_ids_json'].forEach(function(h){arrayIDs(r.json[h],'Asset '+h).forEach(function(id){fk(aMap,r.raw,id,'Asset link');});});if(!/^\d+$/.test(r.raw.field_count))fail('Asset field_count must be a nonnegative integer.');});
 var counts=new Map();fields.rows.forEach(function(r){validateDescription(r.raw,r.json,'description_',r.raw.description,'Field '+r.id);var original=r.json.original_field_json;if(!object(original))fail('Original field metadata must be an object: '+r.id);[['field_name','field_name'],['field_kind','field_kind'],['source_system','system'],['layer','stage'],['data_type','data_type'],['description','description'],['description_origin','description_origin']].forEach(function(pair){if(Object.prototype.hasOwnProperty.call(original,pair[1])&&text(original[pair[1]])!==r.raw[pair[0]])fail('Canonical field metadata disagrees with original '+pair[1]+': '+r.id);});fk(aMap,r.raw,r.raw.asset_id,'Field asset');counts.set(key(r.raw,r.raw.asset_id),(counts.get(key(r.raw,r.raw.asset_id))||0)+1);['upstream_field_ids_json','downstream_field_ids_json'].forEach(function(h){arrayIDs(r.json[h],'Field '+h).forEach(function(id){fk(fMap,r.raw,id,'Field link');});});});
 assets.rows.forEach(function(r){if(Number(r.raw.field_count)!==(counts.get(r.key)||0))fail('Asset field count does not match its field catalog: '+r.id);});
 rows.forEach(function(r){var raw=r.raw;[['source_description_',raw.source_field_id,'source_description'],['snowflake_description_',raw.target_field_id,'snowflake_description']].forEach(function(part){var prefix=part[0];if(!part[1]&&raw.row_kind==='no_documented_target'){validateDescription(raw,r.json,prefix,raw[part[2]],'Dictionary '+r.id);return;}var field=fk(fMap,raw,part[1],'Description field');validateDescription(raw,r.json,prefix,raw[part[2]],'Dictionary '+r.id);if(text(raw[part[2]])!==field.raw.description)fail('Dictionary description text disagrees with field catalog: '+part[1]);descriptionKeys.forEach(function(k){var a=k==='provenance_json'?stable(r.json[prefix+k]):raw[prefix+k],b=k==='provenance_json'?stable(field.json['description_'+k]):field.raw['description_'+k];if(a!==b)fail('Dictionary description '+k+' disagrees with field catalog: '+part[1]);});});
  [['source_field_id','source_asset_id'],['hvr_field_id','hvr_asset_id'],['target_field_id','target_asset_id']].forEach(function(pair){if(!raw[pair[0]]&&raw.row_kind==='no_documented_target'&&pair[0]==='target_field_id')return;var field=fk(fMap,raw,raw[pair[0]],'Dictionary field');fk(aMap,raw,raw[pair[1]],'Dictionary asset');if(field.raw.asset_id!==raw[pair[1]])fail('Dictionary field and asset disagree: '+pair[0]);});
  Object.keys(r.catalog).forEach(function(id){var f=fk(fMap,raw,id,'Embedded catalog');if(stable(f.json.original_field_json)!==stable(r.catalog[id]))fail('Field catalog original metadata disagrees with embedded field: '+id);});
  r.relevantFieldIds=Array.from(new Set([raw.source_field_id,raw.hvr_field_id,raw.target_field_id].concat(r.relevantFieldIds).filter(Boolean)));
 });
 var expectedUp=new Map(),expectedDown=new Map(),expectedIncidents=new Map(),assetUp=new Map(),assetDown=new Map();
 fields.rows.forEach(function(r){expectedUp.set(r.key,new Set());expectedDown.set(r.key,new Set());expectedIncidents.set(r.key,new Set());});assets.rows.forEach(function(r){assetUp.set(r.key,new Set());assetDown.set(r.key,new Set());});
 operations.forEach(function(op,operationKey){var ids=JSON.parse(operationKey),raw={graph_id:ids[0],snapshot_id:ids[1]};op.source_field_ids.forEach(function(input){expectedIncidents.get(key(raw,input)).add(op.relationship_id+'|input');op.target_field_ids.forEach(function(output){expectedDown.get(key(raw,input)).add(output);expectedUp.get(key(raw,output)).add(input);var a=fMap.get(key(raw,input)).raw.asset_id,b=fMap.get(key(raw,output)).raw.asset_id;if(a!==b){assetDown.get(key(raw,a)).add(b);assetUp.get(key(raw,b)).add(a);}});});op.target_field_ids.forEach(function(output){expectedIncidents.get(key(raw,output)).add(op.relationship_id+'|output');});});
 function sameIDs(a,b){return a.length===b.size&&a.every(function(id){return b.has(id);});}
 fields.rows.forEach(function(r){if(!sameIDs(r.json.upstream_field_ids_json,expectedUp.get(r.key))||!sameIDs(r.json.downstream_field_ids_json,expectedDown.get(r.key)))fail('Field topology disagrees with recorded operations: '+r.id);if(!Array.isArray(r.json.transformation_logic_json))fail('Field transformation logic must be an array: '+r.id);var incidents=new Set();r.json.transformation_logic_json.forEach(function(op){if(!object(op)||!['input','output'].includes(op.field_role))fail('Invalid incident relationship for field: '+r.id);var copy=Object.assign({},op);delete copy.field_role;var recorded=operations.get(key(r.raw,op.relationship_id));if(!recorded||stable(copy)!==stable(recorded))fail('Field relationship disagrees with dictionary operation: '+r.id);incidents.add(op.relationship_id+'|'+op.field_role);});if(incidents.size!==r.json.transformation_logic_json.length||!sameIDs(Array.from(incidents),expectedIncidents.get(r.key)))fail('Field incident relationship coverage is incomplete: '+r.id);});
 assets.rows.forEach(function(r){if(!sameIDs(r.json.upstream_asset_ids_json,assetUp.get(r.key))||!sameIDs(r.json.downstream_asset_ids_json,assetDown.get(r.key)))fail('Asset topology disagrees with recorded operations: '+r.id);});
 // Cross-file topology is checked in both directions; a missing reverse edge is not silently repaired.
 fields.rows.forEach(function(r){r.json.upstream_field_ids_json.forEach(function(id){var other=fMap.get(key(r.raw,id));if(!other.json.downstream_field_ids_json.includes(r.id))fail('Asymmetric field topology: '+id+' → '+r.id);});r.json.downstream_field_ids_json.forEach(function(id){var other=fMap.get(key(r.raw,id));if(!other.json.upstream_field_ids_json.includes(r.id))fail('Asymmetric field topology: '+r.id+' → '+id);});});
 assets.rows.forEach(function(r){r.json.upstream_asset_ids_json.forEach(function(id){if(!aMap.get(key(r.raw,id)).json.downstream_asset_ids_json.includes(r.id))fail('Asymmetric asset topology.');});r.json.downstream_asset_ids_json.forEach(function(id){if(!aMap.get(key(r.raw,id)).json.upstream_asset_ids_json.includes(r.id))fail('Asymmetric asset topology.');});});
 return {files:files,manifest:manifest||{},dictionary:{headers:parsed.headers,rows:rows},assets:assets,fields:fields,assetMap:aMap,fieldMap:fMap,operationCount:operations.size,scopes:Array.from(scopes[0]),key:key};
}
root.V3Bundle=Object.freeze({prepareBundle:prepareBundle,assetHeaders:assetHeaders,fieldHeaders:fieldHeaders,mappingHeaders:mappingHeaders,key:key,scope:scope,text:text});
})(window);
